def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    CARDS.mkdir(parents=True, exist_ok=True)
    queue = list(csv.DictReader(QUEUE.open(encoding="utf-8-sig")))
    manifest = {r["slug"]: r for r in csv.DictReader(MANIFEST.open(encoding="utf-8-sig"), delimiter="\t")}
    rows: list[dict[str, str]] = []
    for q in queue:
        slug = q["slug"]
        m = manifest[slug]
        pdf_path = (Path("referenced") / m["category"] / f"{m['year']}_{slug}.pdf").as_posix()
        ann = ANN.get(slug, D(coding_confidence="low", coding_status="pending_full_text_coding"))
        ann.update({
            "priority": q["priority"], "slug": slug, "level": q["level"], "batch": q["batch"],
            "cluster": q["cluster"], "title": m["title"], "year": m["year"],
            "publication_status": m["status"], "source_url": m["source_url"], "pdf_path": pdf_path,
            "verified_date": "2026-08-13",
        })
        if ann["coding_status"] == "NR":
            ann["coding_status"] = "complete" if slug in ANN else "pending_full_text_coding"
        rows.append(ann)

    with OUT_CSV.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=FIELDS, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)

    for row in rows:
        p = int(row["priority"])
        card = CARDS / f"{p:02d}_{row['slug']}.md"
        sections = [
            f"# {row['title']}",
            "",
            f"- 编号：{p:02d} | 精标等级：{row['level']} | 批次：{row['batch']} | 状态：{row['coding_status']} | 置信度：{row['coding_confidence']}",
            f"- 出版状态：{row['publication_status']} | 年份：{row['year']}",
            f"- 来源：{row['source_url']}",
            f"- 本地全文：`{row['pdf_path']}`",
            "",
            "## 任务、拓扑与协调",
            "",
            f"- 任务：{row['task_family']}",
            f"- 拓扑：{row['task_topology']}；载荷路径：{row['simultaneous_load_path']}；拓扑变化：{row['topology_changes']}",
            f"- 角色：{row['actor_stabilizer']}；协调必要性证据：{row['coordination_necessity_evidence']}",
            "",
            "## 传感与部署可实现性",
            "",
            f"- 触觉：{row['tactile_signal']}（{row['sensor_family']}；{row['sensor_sites']}）",
            f"- 训练输入：{row['train_inputs']}",
            f"- 部署输入：{row['deploy_inputs']}",
            f"- 特权信息：训练={row['privileged_training']}；推理={row['privileged_inference']}；未来参考={row['future_reference']}；仿真接触={row['simulator_contacts']}",
            f"- 部署判断：{row['deployment_observability']}",
            "",
            "## 表征与实验",
            "",
            f"- 表征：{row['representation_family']}；单元：{row['representation_unit']}",
            f"- 结构先验：{row['structural_prior']}；来源：{row['structure_source']}；动态性：{row['dynamic_structure']}",
            f"- 目标：预训练={row['pretraining_objective']}；下游={row['downstream_objective']}；物理目标={row['physical_targets']}",
            f"- 规模与拆分：{row['dataset_scale']}；{row['split_unit']}",
            f"- 基线/统计：{row['baselines']}；matched budget={row['matched_budget']}；seeds={row['seeds_stats']}",
            f"- 泛化：对象={row['object_ood']}；传感器={row['sensor_ood']}；形态={row['embodiment_ood']}；拓扑={row['topology_ood']}",
            "",
            "## 三级证据链",
            "",
            f"1. 作者主张：{row['author_claim']}",
            f"2. 可观察证据：{row['observed_evidence']}",
            f"3. 精标判断：支持程度={row['evidence_supports_claim']}。{row['reviewer_inference']}",
            "",
            f"证据位置：{row['evidence_locations']}",
            "",
            "## 对 BiCG-Rep 的决策",
            "",
            f"- 影响：{row['bicg_impact']}",
            f"- 决策：{row['research_decision']}",
            f"- 理由：{row['decision_rationale']}",
            f"- 主要局限：{row['main_limitation']}",
            f"- 未决问题：{row['unresolved_items']}",
            "",
        ]
        card.write_text("\n".join(sections), encoding="utf-8")


if __name__ == "__main__":
    main()
